export default function buildTree(items) {
  const ids = new Set(items.map((item) => item.id));
  const isRoot = (item) => item.parentId == null || !ids.has(item.parentId) || item.parentId === item.id;
  const attach = (parentId) =>
    items
      .filter((item) => (parentId === undefined ? isRoot(item) : !isRoot(item) && item.parentId === parentId))
      .map((item) => ({ ...item, children: attach(item.id) }));
  return attach(undefined);
}
